import yaml

with open('registry.yaml') as f:
    reg = yaml.safe_load(f)

# Find all null FPR experiments
null_exps = {}
for exp_id, exp in reg.get('experiments', {}).items():
    if 'null' in exp_id.lower() or ('a000' in exp_id.lower() and 's4' in exp_id.lower()) or ('a000' in exp_id.lower() and 's5' in exp_id.lower()):
        null_exps[exp_id] = {
            'status': exp.get('status', '?'),
            'conclusion': exp.get('conclusion', ''),
            'server': exp.get('spec', {}).get('server', '?'),
            'gpu': exp.get('spec', {}).get('gpu', '?'),
        }
    # Also catch alpha_sweep_a000_*
    if 'alpha_sweep_a000' in exp_id:
        null_exps[exp_id] = {
            'status': exp.get('status', '?'),
            'conclusion': exp.get('conclusion', ''),
            'server': exp.get('spec', {}).get('server', '?'),
            'gpu': exp.get('spec', {}).get('gpu', '?'),
        }

for exp_id in sorted(null_exps.keys()):
    e = null_exps[exp_id]
    print(f'{exp_id}: status={e[\"status\"]}, conclusion={e[\"conclusion\"]}, server={e[\"server\"]}, gpu={e[\"gpu\"]}')
